const fs = require('fs');
const path = require('path');
const outDir = path.join($json.tender_root, '04_Go_NoGo_Pack');
fs.mkdirSync(outDir, { recursive: true });
const textOut = $json.output_text || $json.output?.[0]?.content?.[0]?.text || '{}';
const parsed = JSON.parse(textOut);
fs.writeFileSync(path.join(outDir, 'requirements_extract.json'), JSON.stringify(parsed, null, 2));
return [{ json: { ...$json, requirements_extract: parsed } }];
